  // ── Legal framework ──────────────────────────────────────────
  legalFrameworkIntro: 'Kuwait\'s constitution Article 40 states "Education in its preliminary stages shall be compulsory" — generally interpreted by Kuwaiti families and legal practitioners to make education (not specifically school attendance) compulsory. Homeschooling is not specifically legislated in Kuwait; substantial 60-70% expatriate population operates under residence permit frameworks.',
  legalFramework: [
    { h: 'Constitutional education framework',           p: 'Kuwait constitution Article 40 makes education in preliminary stages compulsory. This is interpreted broadly by Kuwaiti families to make education (not specifically school attendance) compulsory, permitting homeschooling with an accredited international provider. The Kuwait Homeschool League advocacy group works toward official recognition and integration into the Kuwaiti educational framework.' },
    { h: 'Non-citizen expat families — flexible',         p: 'Kuwait\'s substantial 60-70% expatriate population operates under residence permit frameworks. Expat families typically pursue international curriculum via Smartious without Kuwaiti Ministry of Education primary enrolment constraints. Filipino, Indian, Egyptian, British, American, Iranian, and other expat families operate under this framework.' },
    { h: 'Pre-primary and secondary — unrestricted',     p: 'Children under 6 (pre-primary) and children 12+ (secondary — Cambridge IGCSE Years 10-11, A-Level Years 12-13, IB Diploma) are unrestricted for all Kuwaiti and expat families. This is Smartious\'s core Kuwait delivery window.' },
    { h: 'Kuwait MOHE Scholarship Program alignment',    p: 'Kuwait Ministry of Higher Education Scholarship Program funds 15,000+ Kuwaiti nationals studying in US universities annually. Cambridge A-Level, IB Diploma, and American AP qualifications with strong SAT/ACT scores align with MOHE scholarship application and equivalency requirements. Smartious delivery includes MOHE-pathway university guidance.' },
  ],

